#!/usr/bin/env node
/**
 * Helpers for the "Solo Compatibility" job in build.yml: it runs Solo with
 * this commit's SDK, so an SDK change that breaks Solo fails SDK CI instead of
 * the next Solo dependency bump (#4535).
 *
 * Usage:
 *   node solo-compat.mjs install <packs dir>
 *       installs @hiero-ledger/solo@$SOLO_VERSION into $SOLO_DIR with a root
 *       `overrides` entry pointing the SDK, proto and cryptography packages at
 *       the `pnpm pack` tarballs in <packs dir>, then fails unless Solo
 *       resolves exactly that SDK (require and import)
 *   node solo-compat.mjs new-key
 *       prints a new ED25519 private key (DER hex), generated by the PR's SDK
 *   node solo-compat.mjs check-network
 *       with the PR's SDK, as $ACCOUNT_ID / $ACCOUNT_KEY: checks the account
 *       key, submits a transfer and a topic message, checks the receipts and
 *       finds both on the mirror node
 *
 * Environment:
 *   SOLO_DIR            install directory for Solo (required)
 *   SOLO_VERSION        Solo release to install (install)
 *   CONSENSUS_ENDPOINT  default 127.0.0.1:35211 (one-shot consensus node 0.0.3)
 *   MIRROR_REST_URL     default http://127.0.0.1:38081 (one-shot mirror ingress)
 */

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
    appendFileSync,
    readdirSync,
    readFileSync,
    realpathSync,
    writeFileSync,
} from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const SOLO_DIR = process.env.SOLO_DIR;
const SDK = "@hiero-ledger/sdk";
const PACKAGES = [SDK, "@hiero-ledger/proto", "@hiero-ledger/cryptography"];
const CONSENSUS_ENDPOINT = process.env.CONSENSUS_ENDPOINT || "127.0.0.1:35211";
const MIRROR_REST_URL = process.env.MIRROR_REST_URL || "http://127.0.0.1:38081";
const MIRROR_WAIT_MS = 120_000;

const log = (...parts) => console.log(new Date().toISOString(), ...parts);

function fail(message) {
    console.error(`::error::${message}`);
    process.exit(1);
}

function summary(markdown) {
    if (process.env.GITHUB_STEP_SUMMARY) {
        appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${markdown}\n`);
    }
}

const soloPackageDir = () =>
    path.join(SOLO_DIR, "node_modules", "@hiero-ledger", "solo");

/** The package root that holds `file`: the closest package.json named `name`. */
function packageRoot(file, name) {
    for (
        let dir = path.dirname(file);
        dir !== path.dirname(dir);
        dir = path.dirname(dir)
    ) {
        try {
            const json = JSON.parse(
                readFileSync(path.join(dir, "package.json"), "utf8"),
            );
            if (json.name === name) return realpathSync(dir);
        } catch {
            // no package.json here
        }
    }
    fail(`no ${name} package.json above ${file}`);
}

/** How Solo's own code resolves the SDK: `require` and `import` from Solo's package. */
function resolveFromSolo() {
    const required = createRequire(
        path.join(soloPackageDir(), "package.json"),
    ).resolve(SDK);
    // --eval resolves relative to the working directory, so this is Solo's own import.
    const imported = fileURLToPath(
        execFileSync(
            process.execPath,
            [
                "--input-type=module",
                "--eval",
                `console.log(import.meta.resolve(${JSON.stringify(SDK)}))`,
            ],
            { cwd: soloPackageDir(), encoding: "utf8" },
        ).trim(),
    );
    return { required, imported };
}

function install(packsDir) {
    if (!SOLO_DIR || !process.env.SOLO_VERSION || !packsDir) {
        fail("install needs SOLO_DIR, SOLO_VERSION and a packs directory");
    }
    const tarballs = new Map();
    for (const name of PACKAGES) {
        const prefix = `${name.replace("@", "").replace("/", "-")}-`;
        const file = readdirSync(packsDir).find(
            (f) => f.startsWith(prefix) && f.endsWith(".tgz"),
        );
        if (!file) fail(`no ${prefix}*.tgz in ${packsDir}`);
        tarballs.set(name, path.resolve(packsDir, file));
    }

    writeFileSync(
        path.join(SOLO_DIR, "package.json"),
        JSON.stringify(
            {
                private: true,
                dependencies: {
                    "@hiero-ledger/solo": process.env.SOLO_VERSION,
                },
                overrides: Object.fromEntries(
                    [...tarballs].map(([name, file]) => [name, `file:${file}`]),
                ),
            },
            null,
            2,
        ),
    );
    execFileSync("npm", ["install", "--no-audit", "--no-fund"], {
        cwd: SOLO_DIR,
        stdio: "inherit",
    });

    // Every copy of each package in the tree must be the tarball: npm records
    // the tarball's sha512 as the integrity of a file: dependency.
    const lock = JSON.parse(
        readFileSync(path.join(SOLO_DIR, "package-lock.json"), "utf8"),
    );
    const identities = [];
    for (const [name, file] of tarballs) {
        const integrity = `sha512-${createHash("sha512")
            .update(readFileSync(file))
            .digest("base64")}`;
        const copies = Object.entries(lock.packages).filter(([key]) =>
            key.endsWith(`node_modules/${name}`),
        );
        if (copies.length !== 1) {
            fail(
                `expected one ${name} in the Solo install, found ${
                    copies.map(([key]) => key).join(", ") || "none"
                }`,
            );
        }
        const [key, entry] = copies[0];
        if (entry.integrity !== integrity) {
            fail(
                `${key} is ${entry.resolved} (${entry.integrity}), not the PR tarball ${file} (${integrity})`,
            );
        }
        identities.push({ name, version: entry.version, integrity, key });
    }

    const expected = realpathSync(path.join(SOLO_DIR, "node_modules", SDK));
    const { required, imported } = resolveFromSolo();
    for (const [how, file] of [
        ["require", required],
        ["import", imported],
    ]) {
        const root = packageRoot(file, SDK);
        log(`Solo ${how}("${SDK}") -> ${file}`);
        if (root !== expected)
            fail(
                `Solo's ${how} resolves ${SDK} from ${root}, not the PR package ${expected}`,
            );
    }

    const npmLs = execFileSync("npm", ["ls", SDK, "--all"], {
        cwd: SOLO_DIR,
        encoding: "utf8",
    }).trim();
    const soloVersion = JSON.parse(
        readFileSync(path.join(soloPackageDir(), "package.json"), "utf8"),
    ).version;
    log(npmLs);
    summary(
        [
            "### Solo Compatibility",
            "",
            "| Component | Version |",
            "| --- | --- |",
            `| Solo | ${soloVersion} |`,
            `| Consensus node | ${process.env.CONSENSUS_NODE_VERSION} |`,
            `| Mirror node | ${process.env.MIRROR_NODE_VERSION} |`,
            ...identities.map(
                (p) =>
                    `| ${p.name} (PR build) | ${
                        p.version
                    } \`${p.integrity.slice(0, 27)}...\` |`,
            ),
            "",
            `Commit: \`${process.env.GITHUB_SHA ?? "local"}\``,
            "",
            `Solo resolves the SDK to \`${expected}\` (require: \`${required}\`, import: \`${imported}\`).`,
            "",
            "```text",
            npmLs,
            "```",
        ].join("\n"),
    );
}

/** The SDK exactly as Solo loads it (the ESM entry). */
async function loadSdk() {
    return import(pathToFileURL(resolveFromSolo().imported).href);
}

async function newKey() {
    const { PrivateKey } = await loadSdk();
    console.log(PrivateKey.generateED25519().toStringDer());
}

/** GETs a mirror REST path until it answers 200 and `check` accepts the body. */
async function waitForMirror(apiPath, check) {
    const deadline = Date.now() + MIRROR_WAIT_MS;
    let last = "";
    while (Date.now() < deadline) {
        try {
            const response = await fetch(`${MIRROR_REST_URL}${apiPath}`);
            const text = await response.text();
            last = `${response.status} ${text}`;
            if (response.ok && check(JSON.parse(text))) return;
        } catch (error) {
            last = String(error);
        }
        await new Promise((resolve) => setTimeout(resolve, 2000));
    }
    fail(
        `mirror node never confirmed ${apiPath}; last answer: ${last.slice(
            0,
            500,
        )}`,
    );
}

const mirrorTransactionId = (transactionId) =>
    `${transactionId.accountId}-${transactionId.validStart.seconds}-${String(
        transactionId.validStart.nanos,
    ).padStart(9, "0")}`;

async function checkNetwork() {
    const sdk = await loadSdk();
    const accountId = sdk.AccountId.fromString(process.env.ACCOUNT_ID);
    const key = sdk.PrivateKey.fromStringDer(process.env.ACCOUNT_KEY);
    const client = sdk.Client.forNetwork({
        [CONSENSUS_ENDPOINT]: "0.0.3",
    }).setOperator(accountId, key);

    try {
        // Solo updated the key; the network must hold the new one, and it must sign.
        const info = await new sdk.AccountInfoQuery()
            .setAccountId(accountId)
            .execute(client);
        if (info.key.toString() !== key.publicKey.toString()) {
            fail(
                `account ${accountId} has key ${info.key}, expected ${key.publicKey}`,
            );
        }
        log(`account ${accountId} holds the updated key`);

        const amount = 100_000_000; // 1 hbar in tinybars
        const recipient = "0.0.2";
        const transfer = await new sdk.TransferTransaction()
            .addHbarTransfer(accountId, sdk.Hbar.fromTinybars(-amount))
            .addHbarTransfer(recipient, sdk.Hbar.fromTinybars(amount))
            .execute(client);
        const transferReceipt = await transfer.getReceipt(client);
        log(`transfer ${transfer.transactionId}: ${transferReceipt.status}`);

        const topicReceipt = await (
            await new sdk.TopicCreateTransaction().execute(client)
        ).getReceipt(client);
        const topicId = topicReceipt.topicId;
        const message = `solo compatibility ${
            process.env.GITHUB_SHA ?? "local"
        } ${Date.now()}`;
        const submit = await new sdk.TopicMessageSubmitTransaction()
            .setTopicId(topicId)
            .setMessage(message)
            .execute(client);
        const submitReceipt = await submit.getReceipt(client);
        const sequenceNumber = submitReceipt.topicSequenceNumber.toString();
        log(
            `topic ${topicId} message ${sequenceNumber}: ${submitReceipt.status}`,
        );

        await waitForMirror(
            `/api/v1/transactions/${mirrorTransactionId(
                transfer.transactionId,
            )}`,
            (body) => {
                const tx = body.transactions?.[0];
                return (
                    tx?.result === "SUCCESS" &&
                    tx.transfers.some(
                        (t) => t.account === recipient && t.amount === amount,
                    ) &&
                    tx.transfers.some(
                        (t) =>
                            t.account === accountId.toString() &&
                            t.amount <= -amount,
                    )
                );
            },
        );
        log("mirror node has the transfer");

        await waitForMirror(
            `/api/v1/topics/${topicId}/messages/${sequenceNumber}`,
            (body) =>
                Buffer.from(body.message ?? "", "base64").toString("utf8") ===
                message,
        );
        log("mirror node has the topic message");
    } finally {
        client.close();
    }
}

const [command, ...args] = process.argv.slice(2);
if (!SOLO_DIR) fail("SOLO_DIR is not set");
switch (command) {
    case "install":
        install(args[0]);
        break;
    case "new-key":
        await newKey();
        break;
    case "check-network":
        await checkNetwork();
        break;
    default:
        fail(
            `unknown command "${command}"; use install, new-key or check-network`,
        );
}
